// Fake Calendly webhook bodies, sent in this order to PF Calendly Capture.
// Same cases as darwin/tools/participant-follow-up/fixtures/calendly-events.json in pidgeon-head.
const RR = 'https://api.calendly.com/event_types/ebd64db8-7c09-4e31-bc2e-339065fbb930';
const FAKE_ET = 'https://api.calendly.com/event_types/MOCK-ET-DOES-NOT-EXIST';
const inv = (c) => `https://api.calendly.com/scheduled_events/MOCK-EVT-${c}/invitees/MOCK-INV-${c}`;
const evt = (c) => `https://api.calendly.com/scheduled_events/MOCK-EVT-${c}`;
const UXR = { utm_source: 'uxr_recruiting', utm_medium: 'email', utm_campaign: 'batch_mock-001' };
const cx = (reason) => ({ canceled_by: 'Mock Participant', canceler_type: 'invitee', reason, created_at: '2026-10-02T08:00:00Z' });
const S = ['2026-10-05T09:00:00.000000Z', '2026-10-05T09:30:00.000000Z'];
const S2 = ['2026-10-06T09:00:00.000000Z', '2026-10-06T09:30:00.000000Z'];

function payload(c, first, [start, end], o = {}) {
  return {
    uri: inv(c), email: o.email ?? `aniol.moner+${c.toLowerCase()}@n8n.io`,
    name: `${first} Mock`, first_name: first, last_name: 'Mock',
    status: o.cancel ? 'canceled' : 'active', timezone: 'Europe/Madrid',
    rescheduled: o.rescheduled ?? false, old_invitee: o.old ?? null, new_invitee: o.new ?? null,
    reschedule_url: `https://calendly.com/reschedulings/MOCK-${c}`,
    cancel_url: `https://calendly.com/cancellations/MOCK-${c}`,
    cancellation: o.cancel ?? null, no_show: null, tracking: o.tracking ?? {},
    scheduled_event: {
      uri: evt(c), name: o.name ?? 'Research with n8n', event_type: o.et ?? RR,
      start_time: start, end_time: end, status: o.cancel ? 'canceled' : 'active',
      event_memberships: [{ user: 'https://api.calendly.com/users/MOCK-HOST', user_email: 'aniol.moner@n8n.io', user_name: 'Aniol Moner' }],
    },
  };
}
const created = (p, label) => ({ _label: label, event: 'invitee.created', payload: p });
const canceled = (p, label) => ({ _label: label, event: 'invitee.canceled', payload: p });

const fixtures = [
  created(payload('R1', 'Rita', S, { tracking: UXR }), 'F1 recruiting create: uxr_recruiting, batch_mock-001, link with utm'),
  created(payload('C1', 'Carl', S), 'F2 CD create: continuous_discovery'),
  created(payload('X1', 'Xena', S, { et: FAKE_ET, name: 'Other research' }), 'F3 research create, lookup fails: link = reschedule_url'),
  canceled(payload('C1', 'Carl', S, { cancel: cx('Cannot make it') }), 'F4 cancel C1: canceled, reason saved'),
  created(payload('S1', 'Sara', S), 'F5a reschedule in order: original S1'),
  canceled(payload('S1', 'Sara', S, { rescheduled: true, new: inv('S2'), cancel: cx('Rescheduled') }), 'F5b S1 canceled, rescheduled=true'),
  created(payload('S2', 'Sara', S2, { old: inv('S1') }), 'F5c new S2: S1 rescheduled to S2, S2 active'),
  created(payload('T1', 'Tom', S), 'F6a reschedule out of order: original T1'),
  created(payload('T2', 'Tom', S2, { old: inv('T1') }), 'F6b new T2 before the cancel: T1 rescheduled'),
  canceled(payload('T1', 'Tom', S, { rescheduled: true, new: inv('T2'), cancel: cx('Rescheduled') }), 'F6c T1 cancel last: T1 still rescheduled'),
  canceled(payload('U1', 'Uma', S, { cancel: cx('Changed my mind') }), 'F7a cancel before create: U1 canceled'),
  created(payload('U1', 'Uma', S), 'F7b late create for U1: still canceled'),
  created(payload('R1', 'Rita', S, { tracking: UXR }), 'F9 duplicate delivery of F1: still one R1 row'),
  created(payload('Z1', 'Zoe', S, { email: 'zoe.real.person@example.com' }), 'F8 non-mock email: dropped, no row'),
];
return fixtures.map((f) => ({ json: f }));
